import{_ as t,o as i,c as n,a2 as d}from"./chunks/framework.vLhlLNVn.js";const a="/assets/alias-iot-lampe.BQzv7GX6.svg",m=JSON.parse('{"title":"VIS, Alexa, Google Home und Apple Home","description":"","frontmatter":{"order":7,"adapter":"wled","editLink":"https://github.com/DrozmotiX/ioBroker.wled/edit/main/docs/de/02.anleitungen/07.vis-und-smarthome.md"},"headers":[],"relativePath":"de/adapter/wled/anleitungen/vis-und-smarthome.md","filePath":"de/adapter/wled/anleitungen/vis-und-smarthome.md","lastUpdated":null}'),r={name:"de/adapter/wled/anleitungen/vis-und-smarthome.md"};function s(l,e,o,c,h,u){return i(),n("div",null,[...e[0]||(e[0]=[d('<h1 id="vis-alexa-google-home-und-apple-home" tabindex="-1">VIS, Alexa, Google Home und Apple Home <a class="header-anchor" href="#vis-alexa-google-home-und-apple-home" aria-label="Permalink to &quot;VIS, Alexa, Google Home und Apple Home&quot;">​</a></h1><p><a id="ready-made-vis-view-wled"></a></p><h2 id="gibt-es-eine-fertige-vis-ansicht-fur-die-wled-steuerung" tabindex="-1">Gibt es eine fertige VIS-Ansicht für die WLED-Steuerung? <a class="header-anchor" href="#gibt-es-eine-fertige-vis-ansicht-fur-die-wled-steuerung" aria-label="Permalink to &quot;Gibt es eine fertige VIS-Ansicht für die WLED-Steuerung?&quot;">​</a></h2><p><strong>Kurz:</strong> Nein, der Adapter bringt weder eine fertige VIS-Ansicht noch eigene Widgets mit. Du baust die Steuerung aus den Standard-Widgets von VIS und bindest sie an die Datenpunkte unten. Alternativ bettest du die Weboberfläche des WLED-Geräts per iFrame ein.</p><h3 id="diese-datenpunkte-bindest-du" tabindex="-1">Diese Datenpunkte bindest du <a class="header-anchor" href="#diese-datenpunkte-bindest-du" aria-label="Permalink to &quot;Diese Datenpunkte bindest du&quot;">​</a></h3><p>Alle Datenpunkte liegen unter <code>wled.0.&lt;Gerät&gt;</code>. Für ein Gerät mit einem Segment nimmst du Segment <code>0</code>.</p><table tabindex="0"><thead><tr><th>Bedienelement</th><th>Widget</th><th>Datenpunkt</th><th>Wert</th></tr></thead><tbody><tr><td>Ein/Aus</td><td>Schalter</td><td><code>on</code></td><td><code>true</code> / <code>false</code></td></tr><tr><td>Helligkeit</td><td>Schieberegler</td><td><code>bri</code></td><td>0 bis 255</td></tr><tr><td>Farbe</td><td>Farbwähler</td><td><code>seg.0.col.0_HEX</code></td><td><code>#RRGGBB</code></td></tr><tr><td>Effekt</td><td>Auswahlliste (Dropdown)</td><td><code>seg.0.fx</code></td><td>Nummer, Namen kommen aus dem Datenpunkt</td></tr><tr><td>Palette</td><td>Auswahlliste (Dropdown)</td><td><code>seg.0.pal</code></td><td>Nummer, Namen kommen aus dem Datenpunkt</td></tr><tr><td>Geschwindigkeit des Effekts</td><td>Schieberegler</td><td><code>seg.0.sx</code></td><td>Zahl</td></tr><tr><td>Intensität des Effekts</td><td>Schieberegler</td><td><code>seg.0.ix</code></td><td>Zahl</td></tr><tr><td>Preset</td><td>Tasten oder Zahlenfeld</td><td><code>ps</code></td><td>Nummer des Presets</td></tr></tbody></table><h3 id="so-baust-du-die-ansicht" tabindex="-1">So baust du die Ansicht <a class="header-anchor" href="#so-baust-du-die-ansicht" aria-label="Permalink to &quot;So baust du die Ansicht&quot;">​</a></h3><ol><li>Leg in VIS eine neue Ansicht an.</li><li>Setz einen Schalter und verbinde ihn mit <code>wled.0.&lt;Gerät&gt;.on</code>.</li><li>Setz einen Schieberegler für <code>wled.0.&lt;Gerät&gt;.bri</code> mit Minimum 0 und Maximum 255. Willst du 0 bis 100 %, bindest du stattdessen einen Prozent-Alias (siehe unten).</li><li>Setz einen Farbwähler und verbinde ihn mit <code>wled.0.&lt;Gerät&gt;.seg.0.col.0_HEX</code>.</li><li>Setz zwei Auswahllisten für <code>seg.0.fx</code> und <code>seg.0.pal</code>. Die Namen der Effekte und Paletten stehen im Datenpunkt selbst, du musst sie nicht abtippen.</li><li>Für Presets setzt du eine Taste je Preset, die die Presetnummer in <code>ps</code> schreibt.</li><li>Prüf die Ansicht im Laufzeitmodus: Jede Änderung muss am Streifen sichtbar sein.</li></ol><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>Nimm für den Farbwähler den HEX-Datenpunkt <code>seg.0.col.0_HEX</code>, nicht den RGB-Datenpunkt <code>seg.0.col.0</code>. Der RGB-Datenpunkt erwartet Text wie <code>[255,0,0]</code>, den ein Farbwähler nicht liefert.</p></div><p><strong>Bis v0.9.2:</strong> Schreibst du einen HEX-Wert, setzt der Adapter bei RGBW-Streifen den Weißkanal auf voll, und die Tertiärfarbe <code>seg.0.col.2_HEX</code> wirkt nicht.</p><p><strong>Ab v0.9.3:</strong> Ein 6-stelliger HEX-Wert (<code>#RRGGBB</code>) lässt den Weißkanal unverändert. Mit einem 8-stelligen Wert (<code>#RRGGBBWW</code>) setzt du den Weißkanal mit (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/907" target="_blank" rel="noreferrer">#907</a>). Die Tertiärfarbe <code>2_HEX</code> wirkt (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/906" target="_blank" rel="noreferrer">#906</a>).</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>Ein eigenes Bild je Preset liefert der Adapter nicht. Das löst du in VIS: Leg für jedes Preset ein Bild-Widget an und mach es nur sichtbar, wenn <code>ps</code> die passende Nummer hat.</p></div><h3 id="weboberflache-von-wled-einbetten" tabindex="-1">Weboberfläche von WLED einbetten <a class="header-anchor" href="#weboberflache-von-wled-einbetten" aria-label="Permalink to &quot;Weboberfläche von WLED einbetten&quot;">​</a></h3><p>Willst du alle Funktionen von WLED in VIS haben, bettest du die Weboberfläche des Geräts mit einem iFrame-Widget ein. Als Adresse trägst du <code>http://192.168.x.y</code> ein, die IP deines WLED-Geräts. Die Bedienung läuft dann direkt am Gerät, nicht über den Adapter.</p><p><strong>Siehe auch:</strong></p><ul><li><a href="./../erste-schritte/erste-steuerung#use-brightness-percent-0-100">Wie nutze ich die Helligkeit in Prozent (0 bis 100), zum Beispiel für Alexa?</a></li><li><a href="./effekte-und-presets#switch-wled-presets-via-ps">Wie schalte ich WLED-Presets per Datenpunkt (ps) in VIS, Blockly oder Skript?</a></li><li><a href="#state-use-colour-picker-vis">Welchen Datenpunkt nehme ich für den Farbwähler in VIS, und wie zeige ich die aktuelle Farbe an?</a></li><li><a href="./../fehlerbehebung/farben-und-vis#vis-2-editor-freeze-pick">Warum friert der VIS-2-Editor ein, wenn ich seg.0.fx im Dropdown wähle?</a></li></ul><p><a id="state-use-colour-picker-vis"></a></p><h2 id="welchen-datenpunkt-nehme-ich-fur-den-farbwahler-in-vis-und-wie-zeige-ich-die-aktuelle-farbe-an" tabindex="-1">Welchen Datenpunkt nehme ich für den Farbwähler in VIS, und wie zeige ich die aktuelle Farbe an? <a class="header-anchor" href="#welchen-datenpunkt-nehme-ich-fur-den-farbwahler-in-vis-und-wie-zeige-ich-die-aktuelle-farbe-an" aria-label="Permalink to &quot;Welchen Datenpunkt nehme ich für den Farbwähler in VIS, und wie zeige ich die aktuelle Farbe an?&quot;">​</a></h2><p><em>Dieser Abschnitt wird noch geschrieben.</em></p><p><a id="choose-effect-palette-vis-as"></a></p><h2 id="wie-wahle-ich-effekt-und-palette-in-vis-als-dropdown" tabindex="-1">Wie wähle ich Effekt und Palette in VIS als Dropdown? <a class="header-anchor" href="#wie-wahle-ich-effekt-und-palette-in-vis-als-dropdown" aria-label="Permalink to &quot;Wie wähle ich Effekt und Palette in VIS als Dropdown?&quot;">​</a></h2><p><em>Dieser Abschnitt wird noch geschrieben.</em></p><p><a id="connect-wled-iot-adapter-switch"></a></p><h2 id="wie-binde-ich-wled-in-den-iot-adapter-ein-und-schalte-effekte-presets-und-farbe-per-alexa-oder-google-home" tabindex="-1">Wie binde ich WLED in den iot-Adapter ein und schalte Effekte, Presets und Farbe per Alexa oder Google Home? <a class="header-anchor" href="#wie-binde-ich-wled-in-den-iot-adapter-ein-und-schalte-effekte-presets-und-farbe-per-alexa-oder-google-home" aria-label="Permalink to &quot;Wie binde ich WLED in den iot-Adapter ein und schalte Effekte, Presets und Farbe per Alexa oder Google Home?&quot;">​</a></h2><p><strong>Kurz:</strong> Der Adapter legt keine fertige Lampe für den iot-Adapter an. Du baust sie dir mit einem Alias-Gerät aus <code>on</code>, <code>bri</code> und <code>seg.0.col.0_HEX</code> und gibst ihm im iot-Adapter einen Smart-Namen. Presets und Effekte schaltest du über einen Hilfsdatenpunkt, den Alexa oder Google Home wie eine Szene auslöst.</p><p>Die Datenpunkte des Adapters haben passende Rollen: <code>on</code> ist <code>switch.light</code>, <code>bri</code> ist <code>level.brightness</code> mit 0 bis 255, die Farbe <code>seg.0.col.0_HEX</code> ist <code>level.color.hex</code>. Der iot-Adapter erkennt ein Licht aber erst, wenn diese Teile in einer gemeinsamen Struktur liegen. Diese Struktur legst du mit einem Alias selbst an.</p><p><img src="'+a+`" alt="Schaubild: Alexa oder Google Home sprechen über einen Smart-Namen im iot-Adapter ein Alias-Gerät mit on, helligkeit in Prozent und farbe an, das auf on, bri und seg.0.col.0_HEX des WLED-Geräts zeigt. Für ein Preset löst der Smart-Name einen Hilfsdatenpunkt aus, und ein Skript schreibt die Presetnummer nach ps."></p><h3 id="ein-aus-helligkeit-und-farbe-als-lampe" tabindex="-1">Ein/Aus, Helligkeit und Farbe als Lampe <a class="header-anchor" href="#ein-aus-helligkeit-und-farbe-als-lampe" aria-label="Permalink to &quot;Ein/Aus, Helligkeit und Farbe als Lampe&quot;">​</a></h3><ol><li><p>Öffne im Admin den Reiter „Objekte“ und lege unter <code>alias.0</code> einen Ordner für die Lampe an, zum Beispiel <code>alias.0.WLED.Wohnzimmer</code>.</p></li><li><p>Lege darin drei Datenpunkte an:</p><table tabindex="0"><thead><tr><th>Datenpunkt im Alias</th><th>Rolle</th><th>Typ</th><th>Ziel (<code>alias.id</code>)</th><th>Umrechnung</th></tr></thead><tbody><tr><td><code>on</code></td><td><code>switch.light</code></td><td><code>boolean</code></td><td><code>wled.0.&lt;Gerät&gt;.on</code></td><td>keine</td></tr><tr><td><code>helligkeit</code></td><td><code>level.dimmer</code>, 0 bis 100, Einheit <code>%</code></td><td><code>number</code></td><td><code>wled.0.&lt;Gerät&gt;.bri</code></td><td>Lesen <code>Math.round(val / 2.55)</code>, Schreiben <code>Math.ceil(val * 2.55)</code></td></tr><tr><td><code>farbe</code></td><td><code>level.color.rgb</code></td><td><code>string</code></td><td><code>wled.0.&lt;Gerät&gt;.seg.0.col.0_HEX</code></td><td>keine</td></tr></tbody></table></li><li><p>Öffne den Reiter des iot-Adapters, such dort das Alias-Gerät und gib ihm einen Smart-Namen, zum Beispiel „Wohnzimmer Streifen“.</p></li><li><p>Lass Alexa oder Google Home nach neuen Geräten suchen.</p></li><li><p>Prüf es mit „Wohnzimmer Streifen auf 50 Prozent“: <code>wled.0.&lt;Gerät&gt;.bri</code> muss auf <code>128</code> springen.</p></li></ol><p>Wie du den Prozent-Alias im Einzelnen anlegst, steht unter <a href="./../erste-schritte/erste-steuerung#use-brightness-percent-0-100">Wie nutze ich die Helligkeit in Prozent (0 bis 100), zum Beispiel für Alexa?</a>.</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>Brauchst du nur Ein/Aus und Helligkeit, reicht oft auch ein Smart-Name direkt auf <code>wled.0.&lt;Gerät&gt;.bri</code>. Weil <code>bri</code> Minimum und Maximum hat, rechnet der iot-Adapter Prozent selbst auf 0 bis 255 um.</p></div><h3 id="presets-und-effekte-als-szene" tabindex="-1">Presets und Effekte als Szene <a class="header-anchor" href="#presets-und-effekte-als-szene" aria-label="Permalink to &quot;Presets und Effekte als Szene&quot;">​</a></h3><p>Sprachassistenten kennen keine WLED-Presets oder -Effekte. Du legst darum je Preset einen Hilfsdatenpunkt an, den Alexa oder Google Home einschaltet, und ein kleines Skript schreibt die Presetnummer nach <code>ps</code>.</p><ol><li><p>Leg einen Datenpunkt vom Typ <code>boolean</code> mit der Rolle <code>button</code> an, zum Beispiel <code>0_userdata.0.WLED.Kaminfeuer</code>.</p></li><li><p>Gib ihm im iot-Adapter einen Smart-Namen, zum Beispiel „Kaminfeuer“.</p></li><li><p>Leg im JavaScript-Adapter dieses Skript an. Die <code>5</code> ersetzt du durch die Nummer deines Presets in WLED:</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">on</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ id: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;0_userdata.0.WLED.Kaminfeuer&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, val: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, ack: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }, () </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    setState</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;wled.0.&lt;Gerät&gt;.ps&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span></code></pre></div></li><li><p>Sag „Alexa, schalte Kaminfeuer ein“. <code>wled.0.&lt;Gerät&gt;.ps</code> muss auf <code>5</code> springen.</p></li></ol><p>Genauso kannst du statt <code>ps</code> einen Effekt schreiben, zum Beispiel <code>setState(&#39;wled.0.&lt;Gerät&gt;.seg.0.fx&#39;, 9)</code>. Wie das Schreiben von <code>ps</code> im Einzelnen funktioniert und worauf du dabei achten musst, steht unter <a href="./effekte-und-presets#switch-wled-presets-via-ps">Wie schalte ich WLED-Presets per Datenpunkt (ps) in VIS, Blockly oder Skript?</a>.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>WLED selbst hat eine eigene Alexa-Anbindung, die ohne ioBroker auskommt. Sie läuft direkt in der WLED-Firmware und hat mit dem Adapter nichts zu tun.</p></div><h3 id="grenzen" tabindex="-1">Grenzen <a class="header-anchor" href="#grenzen" aria-label="Permalink to &quot;Grenzen&quot;">​</a></h3><ul><li><strong>Farbe beendet keinen Effekt.</strong> Ein Farbbefehl schreibt nur die Farben des Segments. Läuft gerade ein Effekt, läuft er mit der neuen Farbe weiter. Willst du eine ruhige Farbe, wähl vorher ein Preset mit einem einfarbigen Effekt.</li><li><strong>Ein Alias je Segment.</strong> Das Alias-Gerät oben steuert nur Segment <code>0</code>. Für weitere Segmente brauchst du eigene Aliase auf <code>seg.&lt;Segment&gt;.on</code>, <code>seg.&lt;Segment&gt;.bri</code> und <code>seg.&lt;Segment&gt;.col.0_HEX</code>.</li><li><strong>Effekte und Paletten nur über Hilfsdatenpunkte.</strong> Eine direkte Auswahl per Sprache gibt es nicht.</li><li><strong>Keine Rückmeldung für Szenen.</strong> Der Hilfsdatenpunkt zeigt nicht an, ob das Preset noch aktiv ist.</li></ul><p><strong>Bis v0.9.2:</strong> Schreibt der iot-Adapter eine Farbe auf einen RGBW-Streifen, schaltet der Adapter den Weißkanal auf voll.</p><p><strong>Ab v0.9.3:</strong> Eine Farbe mit 6 Stellen (<code>#RRGGBB</code>) lässt den Weißkanal unverändert (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/907" target="_blank" rel="noreferrer">#907</a>).</p><p><strong>Siehe auch:</strong></p><ul><li><a href="#ready-made-vis-view-wled">Gibt es eine fertige VIS-Ansicht für die WLED-Steuerung?</a></li><li><a href="./farbe#control-white-channel-rgbw-sk6812">Wie steuere ich den Weißkanal (RGBW, SK6812, warmweiß)?</a></li></ul><p><a id="colour-picker-wled-apple-home"></a></p><h2 id="wie-bekomme-ich-einen-farbwahler-fur-wled-in-apple-home-yahka" tabindex="-1">Wie bekomme ich einen Farbwähler für WLED in Apple Home (Yahka)? <a class="header-anchor" href="#wie-bekomme-ich-einen-farbwahler-fur-wled-in-apple-home-yahka" aria-label="Permalink to &quot;Wie bekomme ich einen Farbwähler für WLED in Apple Home (Yahka)?&quot;">​</a></h2><p><em>Dieser Abschnitt wird noch geschrieben.</em></p>`,46)])])}const b=t(r,[["render",s]]);export{m as __pageData,b as default};
